with temp as (select p.product_id , ifnull(p.price*u.units,0) as totalprice , u.units from prices as p left join unitssold as u on u.product_id=p.product_id and u.purchase_date between p.start_date and p.end_date )
select product_id , ifnull(round(sum(totalprice)/sum(units),2),0) as average_price from temp group by product_id